mapper.select:
SELECT DICT_TYPE AS dictType, FIELD_TYPE AS fieldType, FIELD_NAME AS fieldName, parent_id as parentId, REMARKS, TENANT_ID, SELECT_ABLE, SORT_NO FROM la_dict_info WHERE ENABLE_STATE = 1 AND ( TENANT_ID IS NULL
OR TENANT_ID = #{tenantId}
)
AND DICT_TYPE LIKE #{type}
GROUP BY DICT_TYPE,FIELD_TYPE,FIELD_NAME,parent_id,TENANT_ID,REMARKS,SELECT_ABLE,SORT_NO ORDER BY SORT_NO ASC

SELECT DI.ID, DI.DICT_TYPE , DI.FIELD_TYPE , DI.FIELD_NAME , DI.SORT_NO, DI.REMARKS, DI.TENANT_ID, DI.UPDATED_AT , DI.updated_by , DI.created_byUSER , DI.CREATED_AT , DI.ENABLE_STATE , DT.DICT_NAME, DI.EXTRA, DI.SELECT_ABLE FROM la_dict_info DI INNER JOIN la_dict_type DT ON DT.DICT_TYPE = DI.DICT_TYPE WHERE DI.DICT_TYPE = #{dictInfo.dictType} AND ( DI.TENANT_ID IS NULL
OR DI.TENANT_ID = #{dictInfo.tenantId}
)
AND DI.ID = #{dictInfo.id}
OR DI.PARENT_KEYS LIKE #{dictInfo.parentId}
AND DI.RANK2 <= #{dictInfo.rank}

SELECT DI.ID, DI.DICT_TYPE , DI.FIELD_TYPE , DI.FIELD_NAME , DI.SORT_NO, DI.REMARKS, DI.TENANT_ID, DI.UPDATED_AT , DI.updated_by , DI.created_byUSER , DI.CREATED_AT , DI.ENABLE_STATE , DI.PARENT_ID , DI.PARENT_KEYS , DI.EXTRA, DI.SELECT_ABLE FROM la_dict_info DI INNER JOIN la_dict_type DT ON DT.DICT_TYPE = DI.DICT_TYPE WHERE DI.ENABLE_STATE = 1 AND ( DI.TENANT_ID IS NULL
OR DI.TENANT_ID = #{tenantId}
) AND DT.ID IN
#{item}
